def book_flight(access_token, card_id, travel_date, travel_from, travel_to, travel_class, travel_cost, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0323000" if __import__("os").path.isdir("./environment_mix/0323000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    state_rows = _load("state.json")
    state = state_rows[0] if isinstance(state_rows, list) and state_rows else {}
    if not isinstance(state, dict):
        state = {}

    def _audit(status, error_code=None):
        rows = _load("state.json")
        if not isinstance(rows, list):
            rows = []
        if rows:
            s = rows[0] if isinstance(rows[0], dict) else {}
        else:
            s = {}
            rows = [s]
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat()
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        log = s.get("request_log", [])
        if not isinstance(log, list):
            log = []
        log.append({
            "ts": now,
            "endpoint": "book_flight",
            "credential": access_token,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        s["request_log"] = log
        s["request_count"] = int(s.get("request_count", 0) or 0) + 1
        s["last_request_at"] = now
        _save("state.json", rows)

    # Basic rate limiting if configured
    def _rate_limit_check():
        limit = state.get("rate_limit_per_minute")
        if limit is None:
            return None
        try:
            limit = int(limit)
        except Exception:
            return None
        if limit <= 0:
            return None
        log = state.get("request_log", [])
        if not isinstance(log, list):
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in log:
            if not isinstance(r, dict):
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        if recent >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", "RATE_LIMIT")
        return rl

    # Validate token/session
    if not isinstance(access_token, str) or not access_token.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")
    if state.get("token_expires_in") == 0:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access token expired.")
    stored_token = state.get("access_token")
    if stored_token is not None and access_token != stored_token:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid access token.")

    # Validate required fields
    if not isinstance(card_id, str) or not card_id.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "card_id must be a non-empty string.")
    if not isinstance(travel_date, str) or not travel_date.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "travel_date must be a non-empty string in YYYY-MM-DD.")
    if not isinstance(travel_from, str) or not travel_from.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "travel_from must be a non-empty string.")
    if not isinstance(travel_to, str) or not travel_to.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "travel_to must be a non-empty string.")
    if not isinstance(travel_class, str) or not travel_class.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "travel_class must be a non-empty string.")
    try:
        cost = float(travel_cost)
    except Exception:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "travel_cost must be a valid number.")
    if cost <= 0:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "travel_cost must be positive.")

    # Enums from schema
    allowed_from = {"BOS", "CRH", "JFK", "LAX", "OKD", "ORD", "RMS", "SFO"}
    allowed_to = {"BOS", "JFK", "LAX", "ORD", "RMS", "SFO"}
    allowed_class = {"business", "economy", "first"}
    if travel_from not in allowed_from:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"Invalid travel_from: {travel_from}.")
    if travel_to not in allowed_to:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"Invalid travel_to: {travel_to}.")
    if travel_class not in allowed_class:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid travel_class. Must be one of economy, business, first.")

    try:
        datetime.datetime.strptime(travel_date, "%Y-%m-%d")
    except Exception:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid travel_date format. Use YYYY-MM-DD.")

    # Load cards and bookings
    ccl = state.get("credit_card_list", [])
    if ccl is None:
        ccl = []
    if not isinstance(ccl, list):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Stored credit_card_list is invalid.")
    card = None
    for idx, row in enumerate(ccl):
        if isinstance(row, dict) and str(idx) == card_id:
            card = row
            break
    if card is None:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "card_id does not exist.")

    bal = card.get("balance")
    try:
        bal_num = float(bal)
    except Exception:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Card balance is invalid.")
    if bal_num < cost:
        _audit("error", "CONFLICT")
        return _err("CONFLICT", "Insufficient funds.")

    budget = state.get("budget_limit")
    if budget is not None:
        try:
            budget_num = float(budget)
        except Exception:
            budget_num = None
        if budget_num is not None and cost > budget_num:
            _audit("error", "CONFLICT")
            return _err("CONFLICT", "Booking cost exceeds budget limit.")

    # Create booking & charge card
    booking = state.get("booking_record")
    if booking is None or not isinstance(booking, dict):
        booking = {}

    # id generation (7 digits) avoid collision
    seed = state.get("random_seed")
    try:
        seed = int(seed) if seed is not None else 141053
    except Exception:
        seed = 141053
    # simple deterministic-ish generator based on current count/time/seed
    base = (seed + len(booking) + int(datetime.datetime.utcnow().timestamp())) % 9000000
    booking_id = str(1000000 + base)
    if booking_id in booking:
        # linear probe
        for i in range(1, 100):
            cand = str(1000000 + ((base + i) % 9000000))
            if cand not in booking:
                booking_id = cand
                break
        if booking_id in booking:
            _audit("error", "CONFLICT")
            return _err("CONFLICT", "Unable to allocate booking id.")

    transaction_id = str(10000000 + ((seed + int(datetime.datetime.utcnow().timestamp())) % 90000000))

    booking_row = {
        "card_id": card_id,
        "travel_date": travel_date,
        "travel_from": travel_from,
        "travel_to": travel_to,
        "travel_class": travel_class,
        "travel_cost": cost,
        "transaction_id": transaction_id,
        "status": "booked",
        "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat(),
        "canceled_at": None
    }
    booking[booking_id] = booking_row

    # deduct balance
    new_balance = bal_num - cost
    card["balance"] = int(new_balance) if float(int(new_balance)) == float(new_balance) else new_balance

    # persist
    rows = _load("state.json")
    if not isinstance(rows, list):
        rows = []
    if rows and isinstance(rows[0], dict):
        s = rows[0]
    else:
        s = {}
        rows = [s]
    s.update(state)
    s["booking_record"] = booking
    s["credit_card_list"] = ccl
    _save("state.json", rows)

    _audit("ok", None)
    return {
        "booking_id": booking_id,
        "booking": booking_row
    }

