    stored_token = state.get("access_token")
    if stored_token is not None and access_token != stored_token:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid access token.")

    if not isinstance(booking_id, str) or not booking_id.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "booking_id must be a non-empty string.")

    booking = state.get("booking_record")
    if booking is None or not isinstance(booking, dict) or booking_id not in booking:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Booking not found.")

    rec = booking.get(booking_id)
    if not isinstance(rec, dict):
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Booking not found.")

    if rec.get("status") == "canceled":
        _audit("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Booking is already canceled.")

    if rec.get("status") not in (None, "booked"):
        _audit("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Booking is not cancelable from status {rec.get('status')}.")

    # refund to card if possible
    card_id = rec.get("card_id")
    travel_cost = rec.get("travel_cost")
    refund = 0.0
    try:
        refund = float(travel_cost)
    except Exception:
        refund = 0.0

    ccl = state.get("credit_card_list", [])
    if not isinstance(ccl, list):
        ccl = []
    card = None
    for idx, row in enumerate(ccl):
        if isinstance(row, dict) and str(idx) == str(card_id):
            card = row
            break
    if card is not None and refund > 0:
        try:
            bal = float(card.get("balance", 0))
            card["balance"] = int(bal + refund) if float(int(bal + refund)) == float(bal + refund) else (bal + refund)
        except Exception:
            pass

    rec["status"] = "canceled"
    rec["canceled_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat()
    booking[booking_id] = rec

    # persist
    rows_save = _load("state.json")
    if not isinstance(rows_save, list):
        rows_save = []
    if rows_save and isinstance(rows_save[0], dict):
        s = rows_save[0]
    else:
        s = {}
        rows_save = [s]
    s.update(state)
    s["booking_record"] = booking
    s["credit_card_list"] = ccl
    _save("state.json", rows_save)

    _audit("ok", None)
    return {"booking_id": booking_id, "booking": rec}

