def compute_exchange_rate(base_currency, target_currency, value):
    import json, os, math, random
    _S = json.load(open(os.path.join(_DB, 'state.json'), encoding='utf-8'))
    rates = {("USD","RMB"):7,("USD","EUR"):0.8,("USD","JPY"):110,("USD","GBP"):0.7,
             ("USD","CAD"):1.3,("USD","AUD"):1.4,("USD","INR"):70,("USD","RUB"):60,
             ("USD","BRL"):3.8,("USD","MXN"):20}
    for key, val in rates.items():
        if base_currency == key[0] and target_currency == key[1]:
            return {"exchanged_value": float(value * val)}
        if base_currency == key[1] and target_currency == key[0]:
            return {"exchanged_value": round(value / val, 2)}
    return {"error": "No available exchange rate for the given currencies."}

