def get_all_credit_cards(access_token, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0323000" if __import__("os").path.isdir("./environment_mix/0323000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _ensure_state_row():
        rows2 = _load("state.json")
        if not isinstance(rows2, list):
            rows2 = []
        if rows2 and isinstance(rows2[0], dict):
            return rows2, rows2[0]
        s = {}
        rows2 = [s]
        return rows2, s

    def _audit(status, error_code=None, credential=None):
        rows2, s = _ensure_state_row()
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat()
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        log = s.get("request_log", [])
        if not isinstance(log, list):
            log = []
        log.append({
            "ts": now,
            "endpoint": "get_all_credit_cards",
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        s["request_log"] = log
        s["request_count"] = int(s.get("request_count", 0) or 0) + 1
        s["last_request_at"] = now
        _save("state.json", rows2)

    # Validate inputs
    if not isinstance(access_token, str) or not access_token.strip():
        _audit("error", "VALIDATION_ERROR", credential=access_token if isinstance(access_token, str) else None)
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")

    rows, state = _ensure_state_row()

    # Authenticate: accept token if it matches stored access_token OR if store is uninitialized (no token set).
    stored_token = state.get("access_token")
    token_expires_in = state.get("token_expires_in")

    # If a token is configured, enforce that it matches and is not expired (token_expires_in==0 treated as expired).
    if stored_token is not None:
        if access_token != stored_token:
            _audit("error", "UNAUTHORIZED", credential=access_token)
            return _err("UNAUTHORIZED", "Invalid or expired access token.")
        if token_expires_in in (0, "0"):
            _audit("error", "UNAUTHORIZED", credential=access_token)
            return _err("UNAUTHORIZED", "Invalid or expired access token.")

    # Return stored credit cards (empty list is valid)
    cards = state.get("credit_card_list", [])
    if cards is None:
        cards = []
    if not isinstance(cards, list):
        # tolerate corrupted shape by returning empty
        cards = []

    _audit("ok", None, credential=access_token)
    return {
        "credit_cards": cards,
        "count": len(cards)
    }

