        datetime.datetime.strptime(travel_date.strip(), "%Y-%m-%d")
    except ValueError:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid travel_date format. Use YYYY-MM-DD.")

