    # persist
    rows_save = _load("state.json")
    if not isinstance(rows_save, list):
        rows_save = []
    if rows_save and isinstance(rows_save[0], dict):
        s = rows_save[0]
    else:
        s = {}
        rows_save = [s]
    s.update(state)
    s["insurance_purchases"] = purchases
    s["credit_card_list"] = ccl
    _save("state.json", rows_save)

    _audit("ok", None)
    return {"insurance": rec}

