    if (booking_id is None or booking_id == "None") and (insurance_id is None or insurance_id == "None"):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either booking_id or insurance_id must be provided.")

    if booking_id is not None and booking_id != "None" and not isinstance(booking_id, str):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "booking_id must be a string.")
    if insurance_id is not None and insurance_id != "None" and not isinstance(insurance_id, str):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "insurance_id must be a string.")

    invoice = None
    if booking_id is not None and booking_id != "None":
        booking = state.get("booking_record", {})
        if not isinstance(booking, dict) or booking_id not in booking:
            _audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Booking not found.")
        b = booking.get(booking_id)
        if not isinstance(b, dict):
            _audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Booking not found.")
        invoice = {
            "invoice_type": "booking",
            "booking_id": booking_id,
            "line_items": [
                {"description": f"Flight {b.get('travel_from')}→{b.get('travel_to')} ({b.get('travel_class')})", "amount": b.get("travel_cost")}
            ],
            "total": b.get("travel_cost"),
            "transaction_id": b.get("transaction_id"),
            "issued_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat()
        }

    if insurance_id is not None and insurance_id != "None":
        purchases = state.get("insurance_purchases", [])
        if not isinstance(purchases, list):
            purchases = []
        found = None
        for p in purchases:
            if isinstance(p, dict) and p.get("insurance_id") == insurance_id:
                found = p
                break
        if found is None:
            _audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Insurance purchase not found.")
        inv2 = {
            "invoice_type": "insurance",
            "insurance_id": insurance_id,
            "booking_id": found.get("booking_id"),
            "line_items": [
                {"description": f"Insurance ({found.get('insurance_type')})", "amount": found.get("insurance_cost")}
            ],
            "total": found.get("insurance_cost"),
            "transaction_id": found.get("transaction_id"),
            "issued_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat()
        }
        if invoice is not None:
            # both provided: ensure consistent booking
            if invoice.get("booking_id") and inv2.get("booking_id") and invoice["booking_id"] != inv2["booking_id"]:
                _audit("error", "CONFLICT")
                return _err("CONFLICT", "booking_id and insurance_id refer to different purchases.")
        invoice = inv2 if invoice is None else invoice

    _audit("ok", None)
    return {"invoice": invoice}

