    s["budget_limit"] = bl
    s["budget_last_modified"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat()
    _save("state.json", rows_save)

    _audit("ok", None)
    return {"budget_limit": bl, "last_modified": s["budget_last_modified"]}

