def verify_traveler_information(first_name, last_name, date_of_birth, passport_number):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0323000" if __import__("os").path.isdir("./environment_mix/0323000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _audit(status, error_code=None):
        rows2 = _load("state.json")
        if not isinstance(rows2, list):
            rows2 = []
        s = rows2[0] if rows2 and isinstance(rows2[0], dict) else {}
        if not rows2:
            rows2 = [s]
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat()
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        log = s.get("request_log", [])
        if not isinstance(log, list):
            log = []
        log.append({
            "ts": now,
            "endpoint": "verify_traveler_information",
            "credential": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        s["request_log"] = log
        s["request_count"] = int(s.get("request_count", 0) or 0) + 1
        s["last_request_at"] = now
        _save("state.json", rows2)

    # Basic validation per description
    if not isinstance(first_name, str) or not first_name.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "first_name is required.")
    if not isinstance(last_name, str) or not last_name.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "last_name is required.")
    if not isinstance(date_of_birth, str) or not date_of_birth.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "date_of_birth is required in YYYY-MM-DD format.")
    if not isinstance(passport_number, str) or not passport_number.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "passport_number is required.")

    try:
        dob = datetime.datetime.strptime(date_of_birth.strip(), "%Y-%m-%d").date()
    except ValueError:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "date_of_birth must be in YYYY-MM-DD format.")

    today = datetime.datetime.utcnow().date()
    if dob >= today:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "date_of_birth must be in the past.")

    # Avoid overly strict business rules not present in schema; just basic plausibility.
    age = today.year - dob.year - (1 if (today.month, today.day) < (dob.month, dob.day) else 0)
    if age < 0 or age > 120:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "date_of_birth is not plausible.")

    pn = passport_number.strip()
    # Basic passport format: 6-15 alphanumeric characters
    if not (6 <= len(pn) <= 15) or not pn.replace(" ", "").isalnum():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "passport_number format is invalid.")

    # If the datastore includes a logged-in user name, enforce consistency; otherwise allow.
    rows = _load("state.json")
    state = rows[0] if isinstance(rows, list) and rows and isinstance(rows[0], dict) else {}
    sf = state.get("user_first_name")
    sl = state.get("user_last_name")
    if isinstance(sf, str) and sf.strip() and isinstance(sl, str) and sl.strip():
        if sf.strip().lower() != first_name.strip().lower() or sl.strip().lower() != last_name.strip().lower():
            _audit("error", "UNAUTHORIZED")
            return _err(
                "UNAUTHORIZED",
                "Traveler name does not match the authenticated user."
            )

    _audit("ok", None)
    return {
        "verification_status": True,
        "first_name": first_name.strip(),
        "last_name": last_name.strip(),
        "date_of_birth": date_of_birth.strip(),
        "passport_number": pn
    }
